"""Sub-pipelines: the `call` op, which runs a top-level def with bound params."""

import re

from etl.errors import schema_error
from etl.fields import Field, Label, Map
from etl.steps import Op, register

NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')

class DefName(Label):
    """Sub-pipeline name: an identifier, kept exactly as given."""

    def normalize(self, value, path):
        value = super().normalize(value, path)
        if not NAME_RE.match(value):
            raise schema_error("'%s' must match ^[A-Za-z_][A-Za-z0-9_]*$" % self.key, path)
        return value

class ParamValue(Field):
    """JSON scalar or array (of scalars/arrays); objects are not allowed at any depth."""

    def normalize(self, value, path):
        if isinstance(value, list):
            return [self.normalize(v, '%s[%d]' % (path, i)) for i, v in enumerate(value)]
        if not (value is None or isinstance(value, (bool, int, float, str))):
            raise schema_error("'%s' must be a JSON scalar or array" % self.key, path)
        return value

@register
class Call(Op):
    name = 'call'
    fields = (
        DefName('name'),
        Map('params', ParamValue('params values'), required=False, default={}),
    )

    def run(self, step, rows, ctx):
        return ctx.bind(step['params']).run(ctx.defs[step['name']], rows)
