"""Top-level `defs`: named sub-pipelines, and the checks that every `call` resolves without recursion."""

from etl.errors import EtlError, schema_error
from etl.ops.calls import NAME_RE
from etl.steps import Step, StepList

def parse_defs(raw):
    """{name: [Step]} from the request's `defs` object (paths are defs[Name].steps[k])."""
    if not isinstance(raw, dict):
        raise schema_error("'defs' must be an object", 'defs')
    defs = {}
    for name, body in raw.items():
        path = 'defs[%s]' % name
        if not NAME_RE.match(name):
            raise schema_error('def names must match ^[A-Za-z_][A-Za-z0-9_]*$', path)
        if not isinstance(body, dict):
            raise schema_error('def must be an object', path)
        if 'steps' not in body:
            raise schema_error("missing required field 'steps'", path + '.steps')
        defs[name] = StepList('steps').normalize(body['steps'], path + '.steps')
    return defs

def calls_in(v):
    """Every call step in `v`, in order, including those nested in other steps."""
    if isinstance(v, Step):
        if v.op.name == 'call':
            yield v
        for k in sorted(v.values):
            yield from calls_in(v.values[k])
    elif isinstance(v, list):
        for x in v:
            yield from calls_in(x)
    elif isinstance(v, dict):
        for x in v.values():
            yield from calls_in(x)

def check_calls(steps, defs):
    """UNKNOWN_DEF / RECURSION_FORBIDDEN, reported at the offending call's `name`."""
    done = set()

    def visit(steps, stack):
        for call in calls_in(steps):
            name = call['name']
            if name not in defs:
                raise EtlError('UNKNOWN_DEF', "ETL_ERROR: unknown def '%s'" % name, call.at('name'))
            if name in stack:
                raise EtlError('RECURSION_FORBIDDEN', "ETL_ERROR: recursive call to '%s'" % name, call.at('name'))
            if name not in done:
                visit(defs[name], stack + [name])
                done.add(name)

    visit(steps, [])
    for name, body in defs.items():
        if name not in done:
            visit(body, [name])
            done.add(name)
